exercises.solution:
class WaterTank:
    """A water tank that never overflows and never goes below empty."""

    def __init__(self, capacity):
        self.capacity = capacity
        self.level = 0

    def fill(self, litres):
        added = min(litres, self.capacity - self.level)
        self.level += added
        return added

    def use(self, litres):
        given = min(litres, self.level)
        self.level -= given
        return given

    def percent(self):
        return self.level / self.capacity * 100

