exercises.solution:
class Player:
    def __init__(self, name, max_hp=100):
        self.name = name
        self.max_hp = max_hp
        self.hp = max_hp

    def take_damage(self, amount):
        if amount < 0:
            raise ValueError("damage can't be negative")
        self.hp = max(0, self.hp - amount)

    def heal(self, amount):
        self.hp = min(self.max_hp, self.hp + amount)

    def is_alive(self):
        return self.hp > 0

