exercises.solution:
class SavingsGroup:
    def __init__(self, name):
        self.name = name
        self.members = {}   # made here, so every group gets its own dict

    def add_member(self, person):
        if person in self.members:
            raise ValueError(f"{person} is already in {self.name}")
        self.members[person] = 0

    def deposit(self, person, amount):
        if person not in self.members:
            raise ValueError(f"{person} is not a member")
        if amount <= 0:
            raise ValueError("a deposit must be more than 0")
        self.members[person] += amount

    def balance(self, person):
        return self.members[person]

    def total(self):
        return sum(self.members.values())

tests.check:
g = SavingsGroup('Umoja')
g.add_member('Amina')
for args in [('Otieno', 100), ('Amina', 0), ('Amina', -50)]:
    try:
        g.deposit(*args)
        raise AssertionError('deposit%r should raise ValueError' % (args,))
    except ValueError:
        pass
assert g.total() == 0
